export interface Frontmatter {
  title: string;
  date: Date | null;
  tags: string[];
  draft: boolean;
  layout?: string;
  [key: string]: unknown;
}

export interface Page {
  /** Path of the source file relative to the source dir, e.g. "posts/hello.md" */
  sourcePath: string;
  /** URL path, e.g. "/posts/hello/" */
  url: string;
  /** Output path relative to output dir, e.g. "posts/hello/index.html" */
  outputPath: string;
  frontmatter: Frontmatter;
  /** Rendered HTML body (markdown -> html, code highlighted) */
  html: string;
  /** Raw markdown body */
  body: string;
  excerpt: string;
}

export interface SiteConfig {
  title: string;
  url: string;
  description: string;
}

export interface BuildOptions {
  sourceDir: string;
  templateDir: string;
  outputDir: string;
  site?: Partial<SiteConfig>;
  /** Include pages marked draft: true */
  drafts?: boolean;
  /** Extra script injected into every page (used by dev server for live reload) */
  injectScript?: string;
}

export interface BuildResult {
  pages: Page[];
  tags: Map<string, Page[]>;
  /** All files written, relative to outputDir */
  written: string[];
}

import fs from "node:fs/promises";
import path from "node:path";
import matter from "gray-matter";
import { Marked } from "marked";
import { markedHighlight } from "marked-highlight";
import hljs from "highlight.js";
import type { Frontmatter, Page } from "./types.js";

const marked = new Marked(
  markedHighlight({
    langPrefix: "hljs language-",
    highlight(code, lang) {
      const language = hljs.getLanguage(lang) ? lang : "plaintext";
      return hljs.highlight(code, { language }).value;
    },
  }),
);

/** Parse YAML frontmatter + markdown body from raw file contents. */
export function parseFrontmatter(raw: string): { frontmatter: Frontmatter; body: string } {
  const { data, content } = matter(raw);

  let date: Date | null = null;
  if (data.date instanceof Date) date = data.date;
  else if (typeof data.date === "string" || typeof data.date === "number") {
    const d = new Date(data.date);
    if (!Number.isNaN(d.getTime())) date = d;
  }

  let tags: string[] = [];
  if (Array.isArray(data.tags)) tags = data.tags.map(String);
  else if (typeof data.tags === "string") {
    tags = data.tags.split(",").map((t: string) => t.trim()).filter(Boolean);
  }

  const frontmatter: Frontmatter = {
    ...data,
    title: typeof data.title === "string" ? data.title : "",
    date,
    tags,
    draft: data.draft === true,
    layout: typeof data.layout === "string" ? data.layout : undefined,
  };
  return { frontmatter, body: content };
}

/** Render markdown to HTML with syntax-highlighted code blocks. */
export function renderMarkdown(body: string): string {
  return marked.parse(body, { async: false }) as string;
}

/** Derive URL + output path from a source-relative markdown path (pretty URLs). */
export function pathsFor(relPath: string): { url: string; outputPath: string } {
  const posix = relPath.split(path.sep).join("/");
  const noExt = posix.replace(/\.(md|markdown)$/i, "");
  if (noExt === "index" || noExt.endsWith("/index")) {
    const dir = noExt === "index" ? "" : noExt.slice(0, -"/index".length);
    return {
      url: dir ? `/${dir}/` : "/",
      outputPath: dir ? `${dir}/index.html` : "index.html",
    };
  }
  return { url: `/${noExt}/`, outputPath: `${noExt}/index.html` };
}

function makeExcerpt(body: string, maxLen = 200): string {
  const text = body
    .replace(/```[\s\S]*?```/g, "")
    .replace(/[#>*_`[\]()!-]/g, "")
    .replace(/\s+/g, " ")
    .trim();
  return text.length > maxLen ? `${text.slice(0, maxLen)}…` : text;
}

/** Load a single markdown file into a Page. */
export async function loadPage(sourceDir: string, relPath: string): Promise<Page> {
  const raw = await fs.readFile(path.join(sourceDir, relPath), "utf8");
  const { frontmatter, body } = parseFrontmatter(raw);
  const { url, outputPath } = pathsFor(relPath);
  return {
    sourcePath: relPath.split(path.sep).join("/"),
    url,
    outputPath,
    frontmatter,
    body,
    html: renderMarkdown(body),
    excerpt: makeExcerpt(body),
  };
}

/** Recursively find markdown files under dir, returning source-relative paths. */
export async function findMarkdownFiles(dir: string, base = dir): Promise<string[]> {
  const out: string[] = [];
  const entries = await fs.readdir(dir, { withFileTypes: true });
  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) out.push(...(await findMarkdownFiles(full, base)));
    else if (/\.(md|markdown)$/i.test(entry.name)) out.push(path.relative(base, full));
  }
  return out.sort();
}

import fs from "node:fs/promises";
import path from "node:path";
import Handlebars from "handlebars";

export interface TemplateEngine {
  /** Render named layout (file basename without .hbs) with a context. */
  render(layout: string, context: Record<string, unknown>): string;
  has(layout: string): boolean;
  layouts(): string[];
}

function registerHelpers(hb: typeof Handlebars): void {
  hb.registerHelper("formatDate", (date: unknown, fmt?: unknown) => {
    if (!(date instanceof Date) || Number.isNaN(date.getTime())) return "";
    if (fmt === "iso") return date.toISOString();
    return date.toISOString().slice(0, 10);
  });
  hb.registerHelper("limit", (arr: unknown, n: unknown) =>
    Array.isArray(arr) ? arr.slice(0, Number(n)) : [],
  );
  hb.registerHelper("eq", (a: unknown, b: unknown) => a === b);
}

/**
 * Load a Handlebars template directory:
 *  - `<dir>/*.hbs`           -> layouts, addressable by basename
 *  - `<dir>/partials/*.hbs`  -> partials, addressable as {{> name}}
 */
export async function loadTemplates(templateDir: string): Promise<TemplateEngine> {
  const hb = Handlebars.create();
  registerHelpers(hb);

  const compiled = new Map<string, Handlebars.TemplateDelegate>();

  const entries = await fs.readdir(templateDir, { withFileTypes: true });
  for (const entry of entries) {
    if (entry.isFile() && entry.name.endsWith(".hbs")) {
      const src = await fs.readFile(path.join(templateDir, entry.name), "utf8");
      compiled.set(entry.name.replace(/\.hbs$/, ""), hb.compile(src));
    }
  }

  const partialsDir = path.join(templateDir, "partials");
  try {
    for (const name of await fs.readdir(partialsDir)) {
      if (!name.endsWith(".hbs")) continue;
      const src = await fs.readFile(path.join(partialsDir, name), "utf8");
      hb.registerPartial(name.replace(/\.hbs$/, ""), src);
    }
  } catch (err: unknown) {
    if ((err as NodeJS.ErrnoException).code !== "ENOENT") throw err;
  }

  if (!compiled.has("default")) {
    throw new Error(`Template directory ${templateDir} must contain a default.hbs layout`);
  }

  return {
    render(layout, context) {
      const tpl = compiled.get(layout);
      if (!tpl) throw new Error(`Unknown layout "${layout}" (available: ${[...compiled.keys()].join(", ")})`);
      return tpl(context);
    },
    has: (layout) => compiled.has(layout),
    layouts: () => [...compiled.keys()].sort(),
  };
}

export { Handlebars };

import type { Page, SiteConfig } from "./types.js";

function esc(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

/** Generate an RSS 2.0 feed for the newest `limit` dated pages. */
export function generateRss(pages: Page[], site: SiteConfig, limit = 20): string {
  const dated = pages
    .filter((p) => p.frontmatter.date !== null)
    .sort((a, b) => b.frontmatter.date!.getTime() - a.frontmatter.date!.getTime())
    .slice(0, limit);

  const items = dated
    .map((p) => {
      const link = site.url.replace(/\/$/, "") + p.url;
      return [
        "    <item>",
        `      <title>${esc(p.frontmatter.title)}</title>`,
        `      <link>${esc(link)}</link>`,
        `      <guid>${esc(link)}</guid>`,
        `      <pubDate>${p.frontmatter.date!.toUTCString()}</pubDate>`,
        `      <description>${esc(p.excerpt)}</description>`,
        "    </item>",
      ].join("\n");
    })
    .join("\n");

  return [
    `<?xml version="1.0" encoding="UTF-8"?>`,
    `<rss version="2.0">`,
    `  <channel>`,
    `    <title>${esc(site.title)}</title>`,
    `    <link>${esc(site.url)}</link>`,
    `    <description>${esc(site.description)}</description>`,
    `    <lastBuildDate>${new Date().toUTCString()}</lastBuildDate>`,
    items,
    `  </channel>`,
    `</rss>`,
    ``,
  ].join("\n");
}

import fs from "node:fs/promises";
import path from "node:path";
import Handlebars from "handlebars";
import { findMarkdownFiles, loadPage } from "./content.js";
import { loadTemplates, type TemplateEngine } from "./templates.js";
import { generateRss } from "./rss.js";
import type { BuildOptions, BuildResult, Page, SiteConfig } from "./types.js";

const DEFAULT_SITE: SiteConfig = {
  title: "My Site",
  url: "http://localhost:3000",
  description: "",
};

function pickLayout(engine: TemplateEngine, page: Page): string {
  if (page.frontmatter.layout) return page.frontmatter.layout;
  if (engine.has("post")) return "post";
  return "default";
}

function pageContext(page: Page, site: SiteConfig, extra: Record<string, unknown> = {}) {
  return {
    site,
    page: { ...page.frontmatter, url: page.url, excerpt: page.excerpt },
    title: page.frontmatter.title,
    date: page.frontmatter.date,
    tags: page.frontmatter.tags,
    content: new Handlebars.SafeString(page.html),
    ...extra,
  };
}

function injectInto(html: string, script: string): string {
  if (html.includes("</body>")) return html.replace("</body>", `${script}\n</body>`);
  return html + script;
}

async function write(outputDir: string, rel: string, contents: string, written: string[]) {
  const full = path.join(outputDir, rel);
  await fs.mkdir(path.dirname(full), { recursive: true });
  await fs.writeFile(full, contents, "utf8");
  written.push(rel);
}

/** Collect pages grouped by tag. */
export function collectTags(pages: Page[]): Map<string, Page[]> {
  const tags = new Map<string, Page[]>();
  for (const page of pages) {
    for (const tag of page.frontmatter.tags) {
      const list = tags.get(tag) ?? [];
      list.push(page);
      tags.set(tag, list);
    }
  }
  for (const list of tags.values()) {
    list.sort((a, b) => (b.frontmatter.date?.getTime() ?? 0) - (a.frontmatter.date?.getTime() ?? 0));
  }
  return tags;
}

/** Build the whole site: pages, tag indexes, index, RSS feed. */
export async function buildSite(options: BuildOptions): Promise<BuildResult> {
  const site: SiteConfig = { ...DEFAULT_SITE, ...options.site };
  const engine = await loadTemplates(options.templateDir);
  const written: string[] = [];

  const files = await findMarkdownFiles(options.sourceDir);
  const all = await Promise.all(files.map((f) => loadPage(options.sourceDir, f)));
  const pages = all.filter((p) => options.drafts || !p.frontmatter.draft);

  const byDateDesc = [...pages].sort(
    (a, b) => (b.frontmatter.date?.getTime() ?? 0) - (a.frontmatter.date?.getTime() ?? 0),
  );
  const postList = byDateDesc.map((p) => ({
    ...p.frontmatter,
    url: p.url,
    excerpt: p.excerpt,
  }));

  const finish = (html: string) => (options.injectScript ? injectInto(html, options.injectScript) : html);

  // Content pages
  for (const page of pages) {
    const html = engine.render(pickLayout(engine, page), pageContext(page, site, { posts: postList }));
    await write(options.outputDir, page.outputPath, finish(html), written);
  }

  // Tag index pages
  const tags = collectTags(pages);
  const tagLayout = engine.has("tag") ? "tag" : "default";
  for (const [tag, tagged] of tags) {
    const html = engine.render(tagLayout, {
      site,
      title: `Tag: ${tag}`,
      tag,
      posts: tagged.map((p) => ({ ...p.frontmatter, url: p.url, excerpt: p.excerpt })),
      content: "",
    });
    await write(options.outputDir, path.join("tags", tag, "index.html"), finish(html), written);
  }

  // Site index (only if no source index.md provided one)
  if (!pages.some((p) => p.outputPath === "index.html")) {
    const indexLayout = engine.has("index") ? "index" : "default";
    const html = engine.render(indexLayout, {
      site,
      title: site.title,
      posts: postList,
      tags: [...tags.keys()].sort(),
      content: "",
    });
    await write(options.outputDir, "index.html", finish(html), written);
  }

  // RSS
  await write(options.outputDir, "feed.xml", generateRss(pages, site), written);

  return { pages, tags, written };
}

import fs from "node:fs/promises";
import http from "node:http";
import path from "node:path";
import chokidar from "chokidar";
import { WebSocketServer } from "ws";
import { buildSite } from "./build.js";
import type { BuildOptions } from "./types.js";

const MIME: Record<string, string> = {
  ".html": "text/html; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".json": "application/json",
  ".xml": "application/xml",
  ".svg": "image/svg+xml",
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".gif": "image/gif",
  ".ico": "image/x-icon",
  ".txt": "text/plain; charset=utf-8",
};

export function reloadScript(port: number): string {
  return `<script>
(function () {
  var ws = new WebSocket("ws://" + location.hostname + ":${port}");
  ws.onmessage = function (e) { if (e.data === "reload") location.reload(); };
  ws.onclose = function () { setTimeout(function () { location.reload(); }, 1000); };
})();
</script>`;
}

export interface DevServer {
  port: number;
  close(): Promise<void>;
}

export interface ServeOptions extends BuildOptions {
  port?: number;
}

/** Resolve a URL path to a file inside root, guarding against traversal. */
export function resolveStatic(root: string, urlPath: string): string | null {
  const decoded = decodeURIComponent(urlPath.split("?")[0] ?? "/");
  let rel = path.posix.normalize(decoded).replace(/^\/+/, "");
  if (rel === "" || decoded.endsWith("/")) rel = path.posix.join(rel, "index.html");
  const full = path.resolve(root, rel);
  if (!full.startsWith(path.resolve(root) + path.sep) && full !== path.resolve(root)) return null;
  return full;
}

/** Start dev server: initial build, static serving, rebuild + WS reload on change. */
export async function serve(options: ServeOptions): Promise<DevServer> {
  const port = options.port ?? 3000;
  const buildOpts: BuildOptions = { ...options, injectScript: reloadScript(port) };

  await buildSite(buildOpts);

  const server = http.createServer(async (req, res) => {
    const file = resolveStatic(options.outputDir, req.url ?? "/");
    if (!file) {
      res.writeHead(403).end("Forbidden");
      return;
    }
    try {
      let target = file;
      const stat = await fs.stat(target).catch(() => null);
      if (stat?.isDirectory()) target = path.join(target, "index.html");
      const body = await fs.readFile(target);
      res.writeHead(200, { "content-type": MIME[path.extname(target)] ?? "application/octet-stream" });
      res.end(body);
    } catch {
      res.writeHead(404, { "content-type": "text/html; charset=utf-8" });
      res.end(`<h1>404 Not Found</h1>${reloadScript(port)}`);
    }
  });

  const wss = new WebSocketServer({ server });

  let building = false;
  let pending = false;
  const rebuild = async () => {
    if (building) {
      pending = true;
      return;
    }
    building = true;
    try {
      await buildSite(buildOpts);
      for (const client of wss.clients) client.send("reload");
      console.log("[ssg] rebuilt, reload sent");
    } catch (err) {
      console.error("[ssg] rebuild failed:", err);
    } finally {
      building = false;
      if (pending) {
        pending = false;
        void rebuild();
      }
    }
  };

  const watcher = chokidar.watch([options.sourceDir, options.templateDir], {
    ignoreInitial: true,
  });
  watcher.on("all", () => void rebuild());

  await new Promise<void>((resolve) => server.listen(port, resolve));
  console.log(`[ssg] serving ${options.outputDir} at http://localhost:${port}`);

  return {
    port,
    async close() {
      await watcher.close();
      wss.close();
      await new Promise<void>((resolve, reject) =>
        server.close((err) => (err ? reject(err) : resolve())),
      );
    },
  };
}

#!/usr/bin/env node
import { buildSite } from "./build.js";
import { serve } from "./server.js";

export interface CliOptions {
  command: "build" | "serve" | "help";
  sourceDir: string;
  templateDir: string;
  outputDir: string;
  port: number;
  drafts: boolean;
  siteTitle?: string;
  siteUrl?: string;
}

export const USAGE = `ssg - static site generator

Usage:
  ssg build [options]     Build the site once
  ssg serve [options]     Build, serve, watch and live-reload

Options:
  -s, --source <dir>      Source dir of markdown files   (default: content)
  -t, --templates <dir>   Handlebars template dir        (default: templates)
  -o, --output <dir>      Output dir                     (default: dist-site)
  -p, --port <n>          Dev server port                (default: 3000)
      --drafts            Include pages with draft: true
      --site-title <s>    Site title (used in feed/layouts)
      --site-url <s>      Absolute site URL (used in feed)
  -h, --help              Show this help
`;

/** Parse argv (without node/script prefix) into CliOptions. Throws on bad input. */
export function parseArgs(argv: string[]): CliOptions {
  const opts: CliOptions = {
    command: "help",
    sourceDir: "content",
    templateDir: "templates",
    outputDir: "dist-site",
    port: 3000,
    drafts: false,
  };

  const args = [...argv];
  const first = args[0];
  if (first === "build" || first === "serve") {
    opts.command = first;
    args.shift();
  } else if (first === "help" || first === "-h" || first === "--help" || first === undefined) {
    opts.command = "help";
    return opts;
  } else {
    throw new Error(`Unknown command: ${first}`);
  }

  const takeValue = (flag: string): string => {
    const v = args.shift();
    if (v === undefined) throw new Error(`Missing value for ${flag}`);
    return v;
  };

  while (args.length > 0) {
    const arg = args.shift()!;
    switch (arg) {
      case "-s":
      case "--source":
        opts.sourceDir = takeValue(arg);
        break;
      case "-t":
      case "--templates":
        opts.templateDir = takeValue(arg);
        break;
      case "-o":
      case "--output":
        opts.outputDir = takeValue(arg);
        break;
      case "-p":
      case "--port": {
        const n = Number(takeValue(arg));
        if (!Number.isInteger(n) || n < 1 || n > 65535) throw new Error(`Invalid port: ${n}`);
        opts.port = n;
        break;
      }
      case "--drafts":
        opts.drafts = true;
        break;
      case "--site-title":
        opts.siteTitle = takeValue(arg);
        break;
      case "--site-url":
        opts.siteUrl = takeValue(arg);
        break;
      case "-h":
      case "--help":
        opts.command = "help";
        return opts;
      default:
        throw new Error(`Unknown option: ${arg}`);
    }
  }
  return opts;
}

export async function main(argv: string[]): Promise<number> {
  let opts: CliOptions;
  try {
    opts = parseArgs(argv);
  } catch (err) {
    console.error(String(err instanceof Error ? err.message : err));
    console.error(USAGE);
    return 2;
  }

  if (opts.command === "help") {
    console.log(USAGE);
    return 0;
  }

  const site = {
    ...(opts.siteTitle !== undefined ? { title: opts.siteTitle } : {}),
    ...(opts.siteUrl !== undefined ? { url: opts.siteUrl } : {}),
  };

  try {
    if (opts.command === "build") {
      const result = await buildSite({
        sourceDir: opts.sourceDir,
        templateDir: opts.templateDir,
        outputDir: opts.outputDir,
        drafts: opts.drafts,
        site,
      });
      console.log(`[ssg] wrote ${result.written.length} files to ${opts.outputDir}`);
      return 0;
    }
    await serve({
      sourceDir: opts.sourceDir,
      templateDir: opts.templateDir,
      outputDir: opts.outputDir,
      drafts: opts.drafts,
      site,
      port: opts.port,
    });
    return 0;
  } catch (err) {
    console.error(`[ssg] error: ${err instanceof Error ? err.message : String(err)}`);
    return 1;
  }
}

// Only run when executed directly, not when imported by tests.
if (import.meta.url === `file://${process.argv[1]}`) {
  main(process.argv.slice(2)).then((code) => {
    if (code !== 0) process.exitCode = code;
  });
}

import fs from "node:fs/promises";
import os from "node:os";
import path from "node:path";

export async function makeTempDir(): Promise<string> {
  return fs.mkdtemp(path.join(os.tmpdir(), "ssg-test-"));
}

/** Write a tree of files: { "a/b.md": "contents", ... } under root. */
export async function writeTree(root: string, files: Record<string, string>): Promise<void> {
  for (const [rel, contents] of Object.entries(files)) {
    const full = path.join(root, rel);
    await fs.mkdir(path.dirname(full), { recursive: true });
    await fs.writeFile(full, contents, "utf8");
  }
}

